//! A schema library of its own, built as a downstream crate builds one:
//! `layerstack_schemagen` generates its Rust views from its `schema.usda`,
//! and they compile against `layerstack_schemas`' public API alone.
//!
//! - [`lab`], laboratory instruments, is generated by this crate's build
//!   script (`CompiledSchema::rust_module`, included from `OUT_DIR`). It
//!   builds on OpenUSD's `Typed` and `APISchemaBase`, with typed schemas,
//!   a single-apply schema that is a built-in and auto-applied, and a
//!   multiple-apply schema.
//! - [`observatory`](mod@observatory), telescopes, is checked in (`compile --rust`), since it
//!   builds on OpenUSD's `Xformable` and needs OpenUSD's schema sources to
//!   compile; `tests/generated.rs` checks it is current when
//!   `LAYERSTACK_OPENUSD_SOURCE` names an OpenUSD 26.08 checkout.
//!
//! The schemas are `layerstack_conformance`'s schema compiler fixtures
//! (`fixtures/schema_compiler`), whose registry OpenUSD's is checked
//! against there.

#![no_std]

/// The `labInstruments` schema library, generated at build time.
pub mod lab {
    include!(concat!(env!("OUT_DIR"), "/lab.rs"));
}

/// The `observatory` schema library, generated by `compile --rust`.
pub mod observatory {
    include!("generated/observatory.rs");
}
